public static METSOPickSheetController construct()
{
    return new METSOPickSheetController();
}

    public static void main(Args _args)
    {
        WMSOrderTrans WMSOrderTrans;
        int noOfReport, maxNo, Reportcnt;
        METInventItemOrderSetup metInventItemOrderSetup;
        Map reportMap = new Map(Types::Integer, types::String);

        noOfReport = 1;
        maxNo = 1;
        WMSPickingRoute WMSPickingRoute = _args.record();

        if(_args.menuItemName() == "METSOLoadingSheet" && WMSPickingRoute.expeditionStatus == WMSExpeditionStatus::Activated)
        {
            METSOPickSheetController METSOLoadingSheetController = METSOPickSheetController::construct();
            METSOPickSheetContract rdpLoadingContract = new METSOPickSheetContract();
            rdpLoadingContract.parmWMSPickingRouteID(WMSPickingRoute.pickingRouteID);
            rdpLoadingContract.parmReportCount(1);
            METSOLoadingSheetController.parmReportName(ssrsReportStr(METSOPickSheet, Report));
            METSOLoadingSheetController.parmShowDialog(false);
            METSOLoadingSheetController.parmReportContract().parmRdpContract(rdpLoadingContract);
            METSOLoadingSheetController.parmArgs(_args);
            METSOLoadingSheetController.startOperation();
        }
        else if(_args.menuItemName() == "METSOPickSheet" && WMSPickingRoute.expeditionStatus == WMSExpeditionStatus::Activated)
        {
            InventDim InventDim;
            salesLine salesLine;
            while select sum(qty), ItemId, inventTransId from WMSOrderTrans group by routeId,ItemId,inventTransId
            where WMSOrderTrans.routeId == wmsPickingRoute.PickingRouteID
            {
                select  salesLine where salesLine.InventTransId == WMSOrderTrans.inventTransId
                join InventDim where InventDim.inventDimId == salesLine.InventDimId
                join metInventItemOrderSetup
                where metInventItemOrderSetup.ItemId          == salesLine.ItemId
                        && metInventItemOrderSetup.PalletQty
                        && metInventItemOrderSetup.SiteId    == InventDim.InventSiteId;

                if(metInventItemOrderSetup && WMSOrderTrans.qty >  metInventItemOrderSetup.PalletQty)
                {
                    noOfReport = roundUp(WMSOrderTrans.qty /  metInventItemOrderSetup.PalletQty, 1);
                    reportMap.insert(noOfReport, WMSOrderTrans.itemId);
                    if(maxNo < noOfReport)
                    {
                        maxNo = noOfReport;
                    }
                }
            }
            Reportcnt = 1;
            while(Reportcnt <= maxNo)
            {
                METSOPickSheetContract rdpContract = new METSOPickSheetContract();
                rdpContract.parmIsPickSheet(NoYes::Yes);
                rdpContract.parmWMSPickingRouteID(WMSPickingRoute.pickingRouteID);
                rdpContract.parmReportCount(Reportcnt);

                METSOPickSheetController METSOPickSheetController = METSOPickSheetController::construct();
                METSOPickSheetController.parmReportName(ssrsReportStr(METSOPickSheet, Report));
                METSOPickSheetController.parmShowDialog(false);
                METSOPickSheetController.parmReportContract().parmRdpContract(rdpContract);

                SRSPrintDestinationSettings printDestinationSettings = new SRSPrintDestinationSettings();
                printDestinationSettings.parmFileName(WMSPickingRoute.pickingRouteID + '.pdf');
                printDestinationSettings.fileFormat(SRSReportFileFormat::PDF);
                printDestinationSettings.printMediumType(SRSPrintMediumType::File);

                SrsReportDataContract reportDataContract = new SrsReportDataContract();
                reportDataContract.unpack(METSOPickSheetController.parmReportContract().pack());
                reportDataContract.parmReportExecutionInfo(new SRSReportExecutionInfo());
                reportDataContract.parmPrintSettings(printDestinationSettings);

                new SrsReportRunService().runReport(reportDataContract);

                Browser br = new Browser();

                System.IO.Stream stream = new System.IO.MemoryStream(reportDataContract.parmReportBytes());

                str downloadurl = File::SendFileToTempStore(stream, printDestinationSettings.parmFileName(), classstr(FileUploadTemporaryStorageStrategy), true);

                new Browser().navigate(downloadurl, true, false);
                Reportcnt++;
            }
            
        }

       
    }
